function Pill({ children, tone = 'blue' }) {
  const color = tone === 'mint' ? COLORS.mint : tone === 'amber' ? COLORS.amber : tone === 'coral' ? COLORS.coral : COLORS.blue;
  return <View style={[styles.pill, { backgroundColor: `${color}22` }]}><Text style={[styles.pillText, { color }]}>{children}</Text></View>;
}

function Card({ children, style }) { return <View style={[styles.card, style]}>{children}</View>; }

const VinTool = ({ onHome, onUse }) => {
  const [value, setValue] = useState('');
  const [result, setResult] = useState(null);
  const [busy, setBusy] = useState(false);
  const mountedRef = useRef(true);
  useEffect(() => () => { mountedRef.current = false; }, []);
  const runDecode = async () => {
    setBusy(true);
    setResult(null);
    try {
      const decoded = await decodeVin(value);
      if (!mountedRef.current) return;
      setValue(decoded.vin);
      setResult(decoded);
    } catch (error) {
      if (mountedRef.current) setResult({ status: 'error', message: error?.message || 'Enter a valid 17-character VIN before decoding.', vehicle: null });
    } finally {
      if (mountedRef.current) setBusy(false);
    }
  };
  const vehicleLabel = result?.vehicle ? [result.vehicle.year, result.vehicle.make, result.vehicle.model].filter(Boolean).join(' ') : '';
  return <ScrollView contentContainerStyle={styles.content}>
    <Text accessibilityRole="button" accessibilityLabel={getInspectionNavigationLabel('home')} style={styles.back} onPress={onHome}>‹ Home</Text>
    <Text style={styles.pageTitle}>VIN decoder</Text>
    <Text style={styles.pageBody}>Decode a 17-character VIN with the public NHTSA vPIC service.</Text>
    <Text accessibilityLiveRegion="polite" style={styles.muted}>{result?.message || getToolInputGuidance('vin', value)}</Text>
    <Card>
      <TextInput style={styles.inputFull} value={value} onChangeText={setValue} placeholder="Enter VIN" placeholderTextColor={COLORS.muted} autoCapitalize="characters" autoCorrect={false} maxLength={17} returnKeyType="done" onSubmitEditing={runDecode} />
      <TouchableOpacity accessibilityRole="button" accessibilityLabel="Decode VIN" accessibilityState={{ busy, disabled: busy }} disabled={busy} style={[styles.primaryButton, busy && styles.reportActionDisabled]} onPress={runDecode}><Text style={styles.primaryButtonText}>{busy ? 'Decoding…' : 'Decode VIN'}</Text><Text style={styles.buttonArrow}>→</Text></TouchableOpacity>
    </Card>
    {result?.status === 'decoded' ? <Card style={styles.resultCard}><Text style={styles.cardEyebrow}>LIVE RESULT</Text><Text style={styles.cardTitle}>{vehicleLabel || 'Vehicle identity returned'}</Text>{result.vehicle.trim ? <Text style={styles.muted}>Trim: {result.vehicle.trim}</Text> : null}{result.vehicle.bodyClass ? <Text style={styles.muted}>Body: {result.vehicle.bodyClass}</Text> : null}{result.vehicle.engine ? <Text style={styles.muted}>Engine: {result.vehicle.engine}</Text> : null}<TouchableOpacity style={styles.secondaryButton} onPress={() => { onUse({ year: result.vehicle.year, make: result.vehicle.make, model: result.vehicle.model, vin: result.vin }); }}><Text style={styles.secondaryButtonText}>Use in inspection</Text></TouchableOpacity></Card> : null}
    {result?.status === 'fallback' ? <Card style={styles.resultCard}><Text style={styles.cardEyebrow}>OFFLINE FALLBACK</Text><Text style={styles.muted}>No vehicle details were changed. You can retry the lookup or continue entering details manually.</Text></Card> : null}
    {result?.status === 'error' ? <Card style={styles.resultCard}><Text style={styles.cardEyebrow}>CHECK THE VIN</Text><Text style={styles.muted}>{result.message}</Text></Card> : null}
  </ScrollView>;
}

