  useEffect(() => () => { if (undoTimer.current) clearTimeout(undoTimer.current); if (reportActionTimer.current) clearTimeout(reportActionTimer.current); if (persistTimer.current) clearTimeout(persistTimer.current); }, []);

  const prepareBackupExport = () => { const serialized = serializeInspectionBackup({ vehicle, issues, checklist, photos, savedInspections, aiHistory }); const parsed = JSON.parse(serialized); setBackupPreview({ serialized, metadata: getBackupMetadata({ backup: parsed, serialized }) }); };
